import React, { useEffect, useMemo, useState } from 'react';
import { View, Text, TextInput, Button, StyleSheet, FlatList, Linking, Alert } from 'react-native';

export default function MapSearchScreen() {
  const [search, setSearch] = useState('');
  const [locations, setLocations] = useState([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetchLocations('');
  }, []);

  const fetchLocations = async (query = '') => {
    setLoading(true);
    try {
      const response = await fetch(`http://localhost:3000/api/locations?q=${encodeURIComponent(query)}`);
      const data = await response.json();
      setLocations(data);
    } catch (error) {
      Alert.alert('Virhe', 'Sijainteja ei voitu hakea. Tarkista palvelin.');
      setLocations([]);
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = () => {
    fetchLocations(search);
  };

  const openGoogleMaps = (query) => {
    const url = `https://www.google.com/maps/search/${encodeURIComponent(query)}`;
    Linking.openURL(url).catch(() => {
      Alert.alert('Virhe', 'Ei voitu avata Google Mapsia.');
    });
  };

  const results = useMemo(() => locations, [locations]);

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Etsi vuokrattavaa paikkojen läheltä</Text>
      <TextInput
        style={styles.input}
        placeholder="Kirjoita järven, hiihtokeskuksen tai pyöräreitin nimi"
        value={search}
        onChangeText={setSearch}
      />
      <Button title={loading ? 'Haetaan...' : 'Hae'} onPress={handleSearch} disabled={loading} />
      <FlatList
        data={results}
        keyExtractor={(item) => item.id}
        ListEmptyComponent={<Text style={styles.empty}>{loading ? 'Ladataan...' : 'Ei hakutuloksia.'}</Text>}
        renderItem={({ item }) => (
          <View style={styles.card}>
            <Text style={styles.lakeName}>{item.name}</Text>
            <Text style={styles.category}>{item.category}</Text>
            <Text style={styles.place}>{item.place}</Text>
            <Text style={styles.products}>Tarjolla: {item.products.map((p) => p.name).join(', ')}</Text>
            <Button title="Avaa Google Maps" onPress={() => openGoogleMaps(item.query)} />
          </View>
        )}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, padding: 16 },
  title: { fontSize: 20, fontWeight: '700', marginBottom: 12 },
  input: { borderWidth: 1, borderColor: '#ccc', padding: 12, borderRadius: 8, marginBottom: 12 },
  card: { padding: 12, borderWidth: 1, borderColor: '#eee', borderRadius: 10, marginBottom: 12 },
  lakeName: { fontSize: 16, fontWeight: '700' },
  category: { color: '#0077cc', marginBottom: 4 },
  place: { marginBottom: 6, color: '#555' },
  products: { marginBottom: 8, color: '#333' },
  empty: { marginTop: 20, color: '#555' }
});
